<script lang="ts">let { form } = $props();</script><h2>Create event</h2><form method="POST"><label>Title <input name="title" required /></label><label>Description <textarea name="description"></textarea></label><label>Start <input name="startAt" type="datetime-local" required /></label><label>Capacity <input name="capacity" type="number" min="1" /></label><label>Status <select name="status"><option value="draft">Draft</option><option value="open">Open</option><option value="closed">Closed</option></select></label>{#if form?.error}<p role="alert">{form.error}</p>{/if}<button>Create</button></form>
